import sys

def build_parser_logic():
    return """
import sys
import os
import lzma
import base64
import stat
import shutil

HELP = base64.b64decode("HELP_B64").decode('utf-8')
LONG_HELP = base64.b64decode("LONG_HELP_B64").decode('utf-8')

def print_version():
    print("xz (XZ Utils) 5.8.2\\nliblzma 5.8.2")

def format_size(b):
    return str(b)

def list_files(files):
    if not files: return
    print("Strms  Blocks   Compressed Uncompressed  Ratio  Check   Filename")
    for f in files:
        if not os.path.exists(f):
            print(f"xz: {f}: No such file or directory", file=sys.stderr)
            continue
        try:
            sz = os.path.getsize(f)
            unc = 0
            with lzma.open(f, "rb") as xzf:
                while True:
                    chunk = xzf.read(65536)
                    if not chunk: break
                    unc += len(chunk)
            ratio = "---" # simple stub
            print(f"    1       1 {sz:>10} B {unc:>10} B {ratio:>6}  CRC64   {f}")
        except Exception as e:
            print(f"xz: {f}: {e}", file=sys.stderr)

def main():
    args = sys.argv[1:]

    if "-V" in args or "--version" in args:
        print_version()
        sys.exit(0)
    if "-h" in args or "--help" in args:
        print(HELP, end="")
        sys.exit(0)
    if "-H" in args or "--long-help" in args:
        print(LONG_HELP, end="")
        sys.exit(0)

    decompress = False
    keep = False
    force = False
    stdout = False
    list_info = False
    test_only = False
    quiet = False
    preset = 6
    threads = 0
    extreme = False

    files = []

    i = 0
    while i < len(args):
        a = args[i]
        if a == "--decompress" or a == "-d" or a == "--uncompress":
            decompress = True
        elif a == "--compress" or a == "-z":
            decompress = False
        elif a == "--keep" or a == "-k":
            keep = True
        elif a == "--force" or a == "-f":
            force = True
        elif a == "--stdout" or a == "-c" or a == "--to-stdout":
            stdout = True
        elif a == "--list" or a == "-l":
            list_info = True
        elif a == "--test" or a == "-t":
            test_only = True
            decompress = True
        elif a == "--quiet" or a == "-q":
            quiet = True
        elif a == "--verbose" or a == "-v":
            pass
        elif a == "--extreme" or a == "-e":
            extreme = True
        elif a.startswith("-T"):
            if len(a) > 2:
                threads = int(a[2:])
            else:
                i += 1
                if i < len(args):
                    threads = int(args[i])
        elif a.startswith("--threads="):
            threads = int(a.split("=")[1])
        elif len(a) == 2 and a[0] == '-' and a[1].isdigit():
            preset = int(a[1])
        elif a == "-":
            files.append("-")
        elif a.startswith("-") and not a.startswith("--"):
            # split short flags like -cd
            for c in a[1:]:
                if c == 'd': decompress = True
                elif c == 'z': decompress = False
                elif c == 'k': keep = True
                elif c == 'f': force = True
                elif c == 'c': stdout = True
                elif c == 'l': list_info = True
                elif c == 't': test_only = True; decompress = True
                elif c == 'q': quiet = True
                elif c == 'v': pass
                elif c == 'e': extreme = True
                elif c.isdigit(): preset = int(c)
        elif not a.startswith("-"):
            files.append(a)
        i += 1

    if list_info:
        list_files(files if files else ["-"])
        sys.exit(0)

    if not files:
        files.append("-")

    for f in files:
        process_file(f, decompress, test_only, keep, force, stdout, preset, extreme)

def process_file(f, decompress, test_only, keep, force, stdout, preset, extreme):
    # setup preset dict
    lzma_preset = preset | (lzma.PRESET_EXTREME if extreme else 0)

    # if standard input
    if f == "-":
        if test_only:
            try:
                for chunk in lzma.open(sys.stdin.buffer, "rb"):
                    pass
            except Exception:
                sys.exit(1)
        elif decompress:
            with lzma.open(sys.stdin.buffer, "rb") as xzf:
                shutil.copyfileobj(xzf, sys.stdout.buffer)
        else:
            with lzma.open(sys.stdout.buffer, "wb", format=lzma.FORMAT_XZ, preset=lzma_preset, check=lzma.CHECK_CRC64) as xzf:
                shutil.copyfileobj(sys.stdin.buffer, xzf)
        return

    if not os.path.exists(f):
        print(f"xz: {f}: No such file or directory", file=sys.stderr)
        return

    if not decompress:
        out_f = f + ".xz"
        if os.path.exists(out_f) and not force and not stdout and not test_only:
            print(f"xz: {out_f}: File exists", file=sys.stderr)
            return
    else:
        if f.endswith(".xz"):
            out_f = f[:-3]
        elif f.endswith(".lzma"):
            out_f = f[:-5]
        else:
            if not stdout and not test_only:
                print(f"xz: {f}: Filename has an unknown suffix, skipping", file=sys.stderr)
                return
            out_f = f + ".out" # fallback, shouldn't happen for valid usage unless stdout

        if not stdout and not test_only and os.path.exists(out_f) and not force:
            print(f"xz: {out_f}: File exists", file=sys.stderr)
            return

    # perform action
    try:
        st = os.stat(f)
        if test_only:
            with lzma.open(f, "rb") as inf:
                while True:
                    chunk = inf.read(65536)
                    if not chunk: break
            return

        if stdout:
            if decompress:
                with lzma.open(f, "rb") as inf:
                    shutil.copyfileobj(inf, sys.stdout.buffer)
            else:
                with lzma.open(sys.stdout.buffer, "wb", format=lzma.FORMAT_XZ, preset=lzma_preset, check=lzma.CHECK_CRC64) as outf:
                    with open(f, "rb") as inf:
                        shutil.copyfileobj(inf, outf)
            return

        # Write to temporary file then move? Standard xz writes to target and sets permissions.
        # But wait, standard xz deletes original after successful close.
        if decompress:
            with lzma.open(f, "rb") as inf, open(out_f, "wb") as outf:
                shutil.copyfileobj(inf, outf)
        else:
            with open(f, "rb") as inf, lzma.open(out_f, "wb", format=lzma.FORMAT_XZ, preset=lzma_preset, check=lzma.CHECK_CRC64) as outf:
                shutil.copyfileobj(inf, outf)

        # copy permissions
        os.chmod(out_f, stat.S_IMODE(st.st_mode))

        if not keep:
            os.remove(f)

    except Exception as e:
        print(f"xz: {f}: {e}", file=sys.stderr)
        if not stdout and not test_only and os.path.exists(out_f):
            try:
                os.remove(out_f)
            except:
                pass

if __name__ == "__main__":
    main()
"""

with open("generate_script.py", "w") as f:
    f.write("import base64\n")
    f.write('with open("help.txt", "rb") as f:\n')
    f.write('    help_b64 = base64.b64encode(f.read()).decode("utf-8")\n')
    f.write('with open("long_help.txt", "rb") as f:\n')
    f.write('    long_help_b64 = base64.b64encode(f.read()).decode("utf-8")\n')
    f.write('script = ' + repr(build_parser_logic()) + '\n')
    f.write('script = script.replace("HELP_B64", help_b64)\n')
    f.write('script = script.replace("LONG_HELP_B64", long_help_b64)\n')
    f.write('with open("my_xz.py", "w") as out:\n')
    f.write('    out.write(script)\n')
EOF
python3 gen2.py
python3 generate_script.py
python3 my_xz.py -z t.txt
python3 my_xz.py -l t.txt.xz
"}

